<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Import Progress" />
    <Card>
      <CardContent class="flex flex-col gap-6 pt-6">
        <State
          v-if="importStatus === 'PENDING' || importStatus === 'PROCESSING'"
          :title="importStatus === 'PENDING' ? 'Pending' : 'Processing'"
          :description="
            importStatus === 'PENDING'
              ? 'Import is queued and will start shortly.'
              : 'Importing staffing resources from CSV. This may take a few minutes.'
          "
          :icon="Spinner"
          icon-class="size-16 w-16"
        />

        <State
          v-else-if="importStatus === 'SUCCESS'"
          title="Import Complete"
          description="Staffing resources have been imported successfully."
          :icon="CircleCheckIcon"
          icon-class="size-16 w-16 text-green-600"
        />

        <template v-else-if="importStatus === 'FAILED'"
          ><State
            title="Import Failed"
            :md-description="importError?.title || 'An error occurred while importing the file.'"
            :icon="CircleXIcon"
            icon-class="size-16 w-16 text-destructive"
          />
          <AppMarkdown
            v-if="importError?.details"
            :markdown="importError.details"
            class="text-sm text-muted-foreground mt-2"
          />
        </template>

        <AppLoader v-else-if="isLoading" subject="import status" variant="inline" />
        <AppError v-else-if="error" variant="table" title="Failed to check import status" />

        <!-- Summary stats -->
        <div v-if="isFinished && hasCounts" class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 text-sm">
          <Card class="shadow-none">
            <CardContent class="flex flex-col items-center gap-1 p-4">
              <span class="text-2xl font-semibold">{{ importResult?.all_rows_count ?? 0 }}</span>
              <span class="text-xs text-muted-foreground">Total rows</span>
            </CardContent>
          </Card>
          <Card class="shadow-none">
            <CardContent class="flex flex-col items-center gap-1 p-4">
              <span class="text-2xl font-semibold text-green-600">{{ importResult?.inserted_rows_count ?? 0 }}</span>
              <span class="text-xs text-muted-foreground">Inserted</span>
            </CardContent>
          </Card>
          <Card class="shadow-none">
            <CardContent class="flex flex-col items-center gap-1 p-4">
              <span class="text-2xl font-semibold text-blue-600">{{ importResult?.updated_rows_count ?? 0 }}</span>
              <span class="text-xs text-muted-foreground">Updated</span>
            </CardContent>
          </Card>
          <Card class="shadow-none">
            <CardContent class="flex flex-col items-center gap-1 p-4">
              <span class="text-2xl font-semibold text-destructive">{{ importResult?.failed_rows_count ?? 0 }}</span>
              <span class="text-xs text-muted-foreground">Failed</span>
            </CardContent>
          </Card>
          <Card class="shadow-none">
            <CardContent class="flex flex-col items-center gap-1 p-4">
              <span class="text-2xl font-semibold text-orange-500">{{ importResult?.filtered_rows_count ?? 0 }}</span>
              <span class="text-xs text-muted-foreground">Skipped</span>
            </CardContent>
          </Card>
        </div>

        <!-- Row events tables -->
        <div v-if="isFinished && errorEvents.length > 0" class="flex flex-col gap-2">
          <span class="text-sm font-medium text-destructive">Errors ({{ errorEvents.length }})</span>
          <Card class="shadow-none">
            <ResponsiveTable rounded>
              <ResponsiveTableHeader>
                <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
                <ResponsiveTableHead>Issue</ResponsiveTableHead>
                <ResponsiveTableHead>Value</ResponsiveTableHead>
              </ResponsiveTableHeader>
              <ResponsiveTableBody>
                <ResponsiveTableRow
                  v-for="event in errorEvents"
                  :key="`error-${event.row_number}-${event.validation_type}`"
                >
                  <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">{{
                    event.row_number
                  }}</ResponsiveTableCell>
                  <ResponsiveTableCell :cols="3" :cols-sm="3" label="Issue" class="text-xs">{{
                    event.hint
                  }}</ResponsiveTableCell>
                  <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">{{
                    event.input_value ?? '—'
                  }}</ResponsiveTableCell>
                </ResponsiveTableRow>
              </ResponsiveTableBody>
            </ResponsiveTable>
          </Card>
        </div>

        <div v-if="isFinished && warningEvents.length > 0" class="flex flex-col gap-2">
          <span class="text-sm font-medium text-orange-500">Warnings ({{ warningEvents.length }})</span>
          <Card class="shadow-none">
            <ResponsiveTable rounded>
              <ResponsiveTableHeader>
                <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
                <ResponsiveTableHead>Issue</ResponsiveTableHead>
                <ResponsiveTableHead>Value</ResponsiveTableHead>
              </ResponsiveTableHeader>
              <ResponsiveTableBody>
                <ResponsiveTableRow
                  v-for="event in warningEvents"
                  :key="`warn-${event.row_number}-${event.validation_type}`"
                >
                  <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">{{
                    event.row_number
                  }}</ResponsiveTableCell>
                  <ResponsiveTableCell :cols="3" :cols-sm="3" label="Issue" class="text-xs">{{
                    event.hint
                  }}</ResponsiveTableCell>
                  <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">{{
                    event.input_value ?? '—'
                  }}</ResponsiveTableCell>
                </ResponsiveTableRow>
              </ResponsiveTableBody>
            </ResponsiveTable>
          </Card>
        </div>

        <div v-if="isFinished && filteredEvents.length > 0" class="flex flex-col gap-2">
          <span class="text-sm font-medium text-muted-foreground">Skipped rows ({{ filteredEvents.length }})</span>
          <Card class="shadow-none">
            <ResponsiveTable rounded>
              <ResponsiveTableHeader>
                <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
                <ResponsiveTableHead>Reason</ResponsiveTableHead>
                <ResponsiveTableHead>Value</ResponsiveTableHead>
              </ResponsiveTableHeader>
              <ResponsiveTableBody>
                <ResponsiveTableRow
                  v-for="event in filteredEvents"
                  :key="`skip-${event.row_number}-${event.validation_type}`"
                >
                  <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">{{
                    event.row_number
                  }}</ResponsiveTableCell>
                  <ResponsiveTableCell :cols="3" :cols-sm="3" label="Reason" class="text-xs">{{
                    event.hint
                  }}</ResponsiveTableCell>
                  <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">{{
                    event.input_value ?? '—'
                  }}</ResponsiveTableCell>
                </ResponsiveTableRow>
              </ResponsiveTableBody>
            </ResponsiveTable>
          </Card>
        </div>

        <div class="flex gap-2 justify-center">
          <NuxtLink :to="{ name: 'staffing-resources' }">
            <Button variant="outline">Back to Staffing Resources</Button>
          </NuxtLink>
          <NuxtLink v-if="isFinished" :to="{ name: 'staffing-resources-import' }">
            <Button>Import Another File</Button>
          </NuxtLink>
        </div>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import SpinnerSvg from '~/assets/icons/spinner.svg';
import { CircleCheckIcon, CircleXIcon } from 'lucide-vue-next';
import { getLastStaffingContactFileProcessingStatus } from '~/client';

definePageMeta({
  roles: ['admin', 'manager'],
});

useHead({
  title: 'Import Progress',
});

const Spinner = SpinnerSvg;

const route = useRoute('staffing-resources-import-id');
const importId = computed(() => route.params.id as string);

const {
  data: importResult,
  refetch,
  isLoading,
  error,
} = useQuery({
  key: () => ['staffing-contact-import-status', importId.value],
  query: () =>
    getLastStaffingContactFileProcessingStatus({
      composable: '$fetch',
      path: { file_import_id: importId.value },
    }),
  staleTime: 0,
  enabled: () => Boolean(importId.value) && route.name === 'staffing-resources-import-id',
});

const importStatus = computed(() => importResult.value?.status ?? null);
const importError = computed(() => importResult.value?.error_message ?? null);
const isFinished = computed(() => importStatus.value === 'SUCCESS' || importStatus.value === 'FAILED');
const hasCounts = computed(() => importResult.value?.all_rows_count != null);

const rowEvents = computed(() => importResult.value?.row_events ?? []);
const errorEvents = computed(() => rowEvents.value.filter((e) => e.event_type === 'error'));
const warningEvents = computed(() => rowEvents.value.filter((e) => e.event_type === 'warning'));
const filteredEvents = computed(() => rowEvents.value.filter((e) => e.event_type === 'filtered'));

useTimeoutPoll(async () => {
  if (isFinished.value || error.value) return;
  await refetch().catch((err) => {
    console.error('Failed to check import status:', err);
  });
}, 5000);
</script>
